#ifndef UNPACKRAT_TESTS_SUPPORT_WOLFRPG_FIXTURES_H
#define UNPACKRAT_TESTS_SUPPORT_WOLFRPG_FIXTURES_H

#include <cstddef>
#include <cstdint>
#include <span>
#include <string>
#include <vector>

namespace test::support
{
    // A classic DX8 ("DX"/version 8) archive generated by the pinned official UberWolf CLI with
    // pack mode 3 (Wolf RPG v2.225). It is repo-owned test data; no commercial game bytes.
    // Contents: hello.txt ("Owned WolfRPG fixture payload\n") and repeat.bin ("0123456789abcdef"
    // repeated 8192 times). The header tables and both bodies are keyed and compressed.
    [[nodiscard]] std::vector<std::byte> classic_dx8_payload();

    struct synthetic_entry
    {
        std::string name;     // stored in both the upper-case and original-case copies
        std::string contents; // plaintext body
        bool lz_compress = false;
    };

    struct built_archive
    {
        std::vector<std::byte> bytes;
        std::size_t header_offset = 0;      // file offset of the (uncompressed) name table
        std::size_t file_table_offset = 0;  // header-relative offset of the first child DARC_FILEHEAD,
                                            // i.e. the root directory's own record plus one
                                            // sizeof(DARC_FILEHEAD) past the file-table base
        std::size_t root_directory_offset = 0; // header-relative offset of the root DARC_DIRECTORY
    };

    // Builds a keyless classic DX8 archive with a stored (uncompressed) header and the given root
    // files. ``lz_compress`` entries store their body as a literal-only LZ stream; their plaintext
    // must not contain the 0xff keycode byte.
    [[nodiscard]] built_archive build_plain_archive(std::span<const synthetic_entry> entries);

    // A single-entry keyless archive whose body is an LZ stream exercising a back-reference.
    // Plaintext is "ababab"; the stream emits two literals then one distance-2 length-4 copy.
    [[nodiscard]] std::vector<std::byte> build_lz_backref_archive();

    // A single-entry keyless archive whose LZ body expands ``unpacked_size`` bytes of 'A' from a
    // few encoded bytes: one literal seed followed by maximum-length distance-1 copy tokens. It
    // models a small compressed body that legitimately decodes far past any in-memory byte budget.
    // ``unpacked_size`` must be at least 5 and fit in 32 bits.
    [[nodiscard]] std::vector<std::byte> build_lz_expansion_archive(std::uint64_t unpacked_size);

    // Convenience corruptions of a built archive (returned in place).
    void corrupt_signature(std::vector<std::byte> &bytes);
    void set_header_version(std::vector<std::byte> &bytes, std::uint16_t version);
    void truncate_bytes(std::vector<std::byte> &bytes, std::size_t new_size);
    void set_root_file_count(const built_archive &archive, std::vector<std::byte> &bytes, std::uint64_t count);

    // Overwrites the DARC_FILEHEAD.DataSize declared for one root entry, letting a test model an
    // archive whose entry legitimately exceeds any fixed in-memory size cap.
    void set_file_unpacked_size(const built_archive &archive, std::vector<std::byte> &bytes, std::size_t index, std::uint64_t unpacked_size);
} // namespace test::support
#endif
